#!/usr/bin/env python3
"""Create two preview apps from the preserved v6.1.6 archive, no firmware changes."""
import pathlib, sys, zipfile, subprocess, re
archive=pathlib.Path(sys.argv[1]).resolve()
out=pathlib.Path(sys.argv[2]).resolve()
def replace_one(path, old, new):
    s=path.read_text(encoding="utf-8")
    if s.count(old)!=1: raise RuntimeError(f"Unexpected upstream content: {path}: {old[:70]}")
    path.write_text(s.replace(old,new,1),encoding="utf-8")
JS="'use strict';\nfunction offlineAnswer(question,ar){\n const q=String(question).trim().toLowerCase();\n if(!q||/f\\s*[1-9]|عطل\\s*\\d|خطأ\\s*\\d|عدل|اضبط|غير|غيّر|set |change |adjust /.test(q))return null;\n const options=[\n [/^(hello|hi|hey|السلام عليكم|ازيك|اهلا|أهلا|مرحبا)[!.؟\\s]*$/, \"Hello! I can help with WC-01 wiring, operation and troubleshooting. What are you seeing?\", \"أهلاً! أقدر أساعدك في تشغيل WC-01 والتوصيلات والأعطال. إيه اللي بيحصل معاك؟\"],\n [/brownout|restart|reset|ريست|ريستارت|بيفصل|يعيد التشغيل|كونفرتر|buck/, \"A reset can be caused by supply dips, interference or firmware faults. With motor and welding power isolated, test the ESP32 alone from a regulated 5 V supply. Measure VIN and 3.3 V during the event. Do not raise the voltage to hide the problem.\", \"إعادة التشغيل ممكن تكون من هبوط التغذية أو تشويش أو خطأ برمجي. افصل قدرة الموتور واللحام واختبر ESP32 وحده بتغذية 5V منظمة. قس VIN و3.3V أثناء الفصل. ما ترفعش الجهد لإخفاء المشكلة.\"],\n [/relay|ريلاي|رليه|رلي|ريليه/, \"Check the relay module voltage and flyback protection. With welding power isolated, check whether the reset occurs when the coil switches. Use an interface rated for the welder; do not connect a welder directly to GPIO.\", \"راجع جهد موديول الريلاي وحماية ملفه من الجهد العكسي. مع فصل قدرة اللحام، افحص هل الفصل بيحصل لحظة تبديل الريلاي. ممنوع توصيل خرج اللحام مباشرة بالـGPIO.\"],\n [/firmware|ota|رفع.*كود|تحديث.*كنترول|فلاش/, \"Wireless firmware maintenance is not enabled in this preview. Use an approved USB procedure with motor and welder isolated. A signed update and safe rollback must be implemented in the controller before OTA can be enabled.\", \"رفع كود الكنترول لاسلكيًا غير متاح في المعاينة دي. استخدم تحديث USB معتمد مع عزل قدرة الموتور واللحام. لازم الكنترول يدعم التوقيع والتحقق والرجوع الآمن قبل تفعيل OTA.\"],\n [/router|راوتر|عدة ماكينات|multi.machine|شبكة المكان/, \"Current firmware uses the controller's own Wi-Fi access point. Shared-router discovery and individually authenticated machines need controller-side support; this preview does not claim to provide it.\", \"الكنترول الحالي بيستخدم شبكة Wi-Fi الخاصة بيه. اكتشاف الماكينات على راوتر المكان وربط كل ماكينة بهوية ومفتاح مستقل محتاج تطوير في الكنترول نفسه؛ مش متاح هنا.\"],\n [/emergency|e.stop|طوارئ|امرجنسي|إيقاف طارئ/, \"The physical emergency stop and hardwired protection must work independently of the application. Never use a phone button as the only emergency stop.\", \"زر الطوارئ والحمايات السلكية لازم تشتغل مستقل عن التطبيق. زرار الموبايل مش بديل لزر الطوارئ الحقيقي.\"],\n [/steps|lead screw|اسكرو|خطوة|خطوه|الميكروستيب/, \"Distance depends on screw lead, motor steps per revolution and driver microstepping. Verify each value against the actual hardware, and calibrate with welding output isolated.\", \"المسافة بتعتمد على مشوار الاسكرو لكل لفة وعدد خطوات الموتور والـMicrostep في الدرايفر. راجع القيم الفعلية واعمل معايرة مع فصل خرج اللحام.\"]\n ];for(const [pattern,en,arabic] of options)if(pattern.test(q))return ar?arabic:en;return null;\n}\n(function(){\nconst el=id=>document.getElementById(id), ar=()=>document.documentElement.lang==='ar'||document.documentElement.dir==='rtl';\nconst msg=(a,b)=>ar()?b:a;\nconst history=el('editionHistory'),ask=el('assistantAsk'),input=el('assistantInput'),reply=el('assistantReply'),apply=el('assistantApply');\nif(!history||!ask||!input||!reply||!apply)return;\nfunction bubble(kind,value){const d=document.createElement('div');d.className='edition-bubble '+kind;d.textContent=value;history.appendChild(d);while(history.children.length>20)history.firstChild.remove();history.scrollTop=history.scrollHeight;}\nask.addEventListener('click',()=>{const q=input.value.trim();if(!q)return;const helpful=offlineAnswer(q,ar());if(helpful&&apply.classList.contains('hidden'))reply.textContent=helpful;bubble('user',q);bubble('helper',reply.textContent);input.value='';});\nfor(const button of document.querySelectorAll('[data-help-question]'))button.addEventListener('click',()=>{input.value=ar()?button.dataset.ar:button.dataset.helpQuestion;input.focus();});\nconst clear=el('editionClear');if(clear)clear.addEventListener('click',()=>history.replaceChildren());\nconst diag=el('engineeringDiagnostics');if(diag)diag.addEventListener('click',()=>el('assistantFab').click());\nconst machine=el('engineeringMachine');if(machine)machine.addEventListener('click',()=>document.querySelector('[data-go=\"machine\"]')?.click());\n})();\n"
CSS="/* Additive edition styling; controller state and safety styles unchanged. */\n.edition-tag{display:block;font-size:10px;letter-spacing:.13em;font-weight:750;color:#e5bd76;margin-top:3px}.edition-banner{padding:14px 16px;margin:12px 0;border:1px solid rgba(225,185,106,.3);border-radius:18px;background:linear-gradient(145deg,#16273d,#101722);color:#f5f7fa}.edition-banner b{font-size:14px;display:block;letter-spacing:.04em}.edition-banner p{font-size:12px;line-height:1.55;color:#b8c5d3;margin:6px 0 0}.edition-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.edition-actions button,.edition-chips button{background:#223549;color:#f2f5fa;border:1px solid #435b73;border-radius:10px;padding:8px 10px;font-size:12px;cursor:pointer}.edition-history{display:flex;flex-direction:column;gap:8px;max-height:210px;overflow:auto;margin:10px 0;overscroll-behavior:contain}.edition-bubble{padding:10px 12px;line-height:1.55;font-size:13px;border-radius:14px;white-space:pre-wrap;overflow-wrap:anywhere;max-width:90%}.edition-bubble.user{align-self:flex-end;background:#295477;color:#fff}.edition-bubble.helper{align-self:flex-start;background:#1a2d42;color:#f4f6fa;border:1px solid #354c64}.edition-chips{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.edition-clear{font-size:12px;color:inherit;background:transparent;border:0;text-decoration:underline}.edition-assistant-note{font-size:11px;color:inherit;opacity:.75;margin:6px 0}.edition-engineering .edition-banner{border-color:#4a9ec8;background:linear-gradient(135deg,#102c40,#101922)}\n"
for edition in ("customer","engineering"):
    root=out/edition
    root.mkdir(parents=True, exist_ok=False)
    with zipfile.ZipFile(archive) as z:
        for item in z.infolist():
            p=pathlib.PurePosixPath(item.filename)
            if p.is_absolute() or ".." in p.parts: raise RuntimeError("Unsafe zip path")
        z.extractall(root)
    app=root/"android/app"
    g=app/"build.gradle.kts"
    label="uArt Engineering" if edition=="engineering" else "uArt Customer"
    # Keep customer app ID compatible; engineering has its own installation.
    if edition=="engineering":
        replace_one(g,'applicationId = "com.uart.wc01"','applicationId = "com.uart.wc01.engineering"')
    replace_one(g,'versionCode = 17','versionCode = 18')
    replace_one(g,'versionName = "6.1.6"', 'versionName = "6.2.0-'+edition+'-preview"')
    replace_one(app/"src/main/AndroidManifest.xml",'android:label="uArt WC-01"','android:label="'+label+'"')
    assets=app/"src/main/assets"
    html=assets/"index.html"
    replace_one(html,'<body>','<body class="edition-'+edition+'">')
    replace_one(html,'<small>INDUSTRIAL CONTROL</small>','<small>INDUSTRIAL CONTROL</small><span class="edition-tag">'+edition.upper()+' · PREVIEW</span>')
    panel='<div class="edition-banner"><b>'+label+' · 6.2 Preview</b>'
    if edition=="engineering":
        panel+='<p>Service workspace / مساحة الصيانة<br>Local controller diagnostics and machine information. LAN fleet and signed OTA are not enabled.</p><div class="edition-actions"><button type="button" id="engineeringDiagnostics">Diagnostics / التشخيص</button><button type="button" id="engineeringMachine">Machine / الماكينة</button></div>'
    else:
        panel+='<p>Operator edition / نسخة التشغيل<br>Live WC-01 control with the existing controller interlocks.</p>'
    panel+='</div>'
    replace_one(html,'<div id="connectionBar" class="status-card">',panel+'<div id="connectionBar" class="status-card">')
    controls='<p class="edition-assistant-note">Offline rule-based help · مساعد محلي بالقواعد · Not a generative AI model</p><div class="edition-chips"><button type="button" data-help-question="Why does ESP32 restart?" data-ar="ESP32 بيفصل ليه؟">Power / التغذية</button><button type="button" data-help-question="How do I check the relay?" data-ar="ازاي أفحص الريلاي؟">Relay / الريلاي</button><button type="button" data-help-question="How does HOME work?" data-ar="ازاي HOME بيشتغل؟">HOME</button></div><div id="editionHistory" class="edition-history" aria-label="Conversation history"></div><button type="button" id="editionClear" class="edition-clear">Clear chat / مسح المحادثة</button>'
    replace_one(html,'<div class="assistant-reply" id="assistantReply" aria-live="polite"></div>',controls+'<div class="assistant-reply" id="assistantReply" aria-live="polite"></div>')
    replace_one(html,'<script src="js/app.js"></script>','<script src="js/app.js"></script>\n<script src="js/edition.js"></script>')
    (assets/"js/edition.js").write_text(JS,encoding="utf-8")
    with (assets/"css/style.css").open("a",encoding="utf-8") as f: f.write("\n"+CSS)
    for path in (assets/"js/app.js", assets/"js/diagnostics.js",assets/"js/edition.js"):
        subprocess.run(["node","--check",str(path)],check=True)
    print("Prepared",edition)
